public class Main {
    public static void main(String[] args) {
        int[] values = {10, 20, 30, 40};
        System.out.println(values[2]); // direct indexing
    }
}

public class Main {
    public static void main(String[] args) {
        int[] a = {10, 20, 30, 40, 0};
        int size = 4, index = 2, value = 99;
        for (int i = size; i > index; i--) a[i] = a[i - 1];
        a[index] = value;
        for (int i = 0; i <= size; i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(a[i]);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int[] a = {10, 20, 30, 40, 50};
        int size = a.length, index = 2;
        for (int i = index; i < size - 1; i++) a[i] = a[i + 1];
        for (int i = 0; i < size - 1; i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(a[i]);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int[] left = {1, 2, 3};
        int[] right = {4, 5};
        int[] merged = new int[left.length + right.length];
        System.arraycopy(left, 0, merged, 0, left.length);
        System.arraycopy(right, 0, merged, left.length, right.length);
        for (int i = 0; i < merged.length; i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(merged[i]);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int n = 5;
        int index = 0; // access is O(1)
        System.out.println("Access: " + index + " -> O(1)");
        System.out.println("Insertion/deletion: O(n) in the worst case");
        System.out.println("Traversal: O(n)");
    }
}

